// Auto-generated EfficientNet-B3 Classifier Weights for True Class Activation Mapping (CAM)
// Dimensions: 1536 channels x 5 DR classes = 7680 float32 values (30 KB)
const CAM_WEIGHTS_B64 = '';

let cachedWeights = null;

export function getCamWeights() {
    if (cachedWeights) return cachedWeights;
    const binary = atob(CAM_WEIGHTS_B64);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) {
        bytes[i] = binary.charCodeAt(i);
    }
    cachedWeights = new Float32Array(bytes.buffer);
    return cachedWeights;
}
